files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

:root {
  --bg: #1a1c2c;
  --card: #2a2d3e;
  --accent: #ffcd75;
  --accent-dark: #e0a83a;
  --text: #f4f4f8;
  --muted: #a0a4b8;
  --danger: #ef7d57;
  --radius: 0;
  --pixel: 4px;
  font-size: 16px;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image:
    linear-gradient(45deg, rgba(255,255,255,0.03) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(255,255,255,0.03) 25%, transparent 25%);
  background-size: 16px 16px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  color: var(--text);
  padding: 24px;
}

.card {
  background: var(--card);
  border: var(--pixel) solid var(--accent);
  box-shadow: var(--pixel) var(--pixel) 0 var(--accent-dark);
  padding: 24px;
  width: 100%;
  max-width: 420px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.title {
  margin: 0;
  font-size: 1.5rem;
  text-align: center;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
}

.timer {
  border: 2px solid var(--muted);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.timer-label {
  margin: 0;
  font-size: 1.125rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
}

.timer-display {
  margin: 0;
  font-size: 2.5rem;
  font-variant-numeric: tabular-nums;
  font-family: ui-monospace, 'Cascadia Code', 'Courier New', monospace;
  color: var(--accent);
  line-height: 1.1;
  word-break: break-word;
}

.timer-display.done {
  color: var(--danger);
  animation: blink 1s steps(2, start) infinite;
}

@keyframes blink {
  to { visibility: hidden; }
}

.timer-controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.btn {
  flex: 1 1 auto;
  min-width: 110px;
  min-height: 48px;
  padding: 8px 16px;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--bg);
  background: var(--accent);
  border: var(--pixel) solid var(--accent-dark);
  box-shadow: var(--pixel) var(--pixel) 0 var(--accent-dark);
  cursor: pointer;
  transition: background 0.1s, transform 0.05s, box-shadow 0.05s;
}

.btn:hover {
  background: #ffe08a;
}

.btn:active {
  transform: translate(var(--pixel), var(--pixel));
  box-shadow: none;
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn-reset {
  background: var(--muted);
  border-color: #7a7e92;
  box-shadow: var(--pixel) var(--pixel) 0 #7a7e92;
  color: var(--text);
}

.btn-reset:hover {
  background: #b8bcd0;
}

@media (max-width: 400px) {
  body {
    padding: 12px;
  }
  .card {
    padding: 16px;
  }
  .timer-display {
    font-size: 2rem;
  }
  .btn {
    min-width: 90px;
    font-size: 0.9375rem;
  }
}

(function () {
  'use strict';

  var timers = [
    { id: 'eggs', duration: 360 },
    { id: 'pasta', duration: 540 },
    { id: 'tea', duration: 180 }
  ];

  function formatTime(seconds) {
    var m = Math.floor(seconds / 60);
    var s = seconds % 60;
    return (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
  }

  timers.forEach(function (timer) {
    var state = {
      remaining: timer.duration,
      running: false,
      intervalId: null
    };

    var display = document.getElementById(timer.id + '-display');
    var toggleBtn = document.getElementById(timer.id + '-toggle');
    var resetBtn = document.getElementById(timer.id + '-reset');
    var label = document.getElementById(timer.id + '-label').textContent;

    function render() {
      if (state.remaining <= 0) {
        display.textContent = 'Done!';
        display.classList.add('done');
      } else {
        display.textContent = formatTime(state.remaining);
        display.classList.remove('done');
      }
    }

    function stopInterval() {
      if (state.intervalId !== null) {
        clearInterval(state.intervalId);
        state.intervalId = null;
      }
      state.running = false;
      toggleBtn.textContent = 'Start';
      toggleBtn.setAttribute('aria-label', 'Start ' + label + ' timer');
    }

    function tick() {
      if (state.remaining > 0) {
        state.remaining -= 1;
      }
      if (state.remaining <= 0) {
        state.remaining = 0;
        render();
        stopInterval();
      } else {
        render();
      }
    }

    function start() {
      if (state.running || state.remaining <= 0) return;
      state.running = true;
      toggleBtn.textContent = 'Pause';
      toggleBtn.setAttribute('aria-label', 'Pause ' + label + ' timer');
      state.intervalId = setInterval(tick, 1000);
    }

    function pause() {
      stopInterval();
    }

    function reset() {
      stopInterval();
      state.remaining = timer.duration;
      render();
    }

    toggleBtn.addEventListener('click', function () {
      if (state.running) {
        pause();
      } else {
        start();
      }
    });

    resetBtn.addEventListener('click', reset);

    render();
  });
})();
